content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_booth_cut",
 "name": "Cluster Puck: a cut to the booth",
 "set": "set_slush_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Hats are coming down. That's three for {cutMan.name}.",
     "{cutMan.name} has a hat trick, and they're throwing everything on the ice."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "cutMan",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "hattrick"
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{cutMan.name} ties it in the third. {away} {awayScore}, {home} {homeScore}.",
     "We're level. {cutMan.name} with the goal, and it's {awayScore} apiece."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{cutMan.name} puts {cutMan.team} in front, late in the third.",
     "There's the go-ahead goal. {cutMan.name}, and {cutMan.team} lead."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "false"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{cutMan.name} and {cutLoser.name} are headed to the box. {cutMan.name} won that one.",
     "That one's over. {cutMan.name} got the better of {cutLoser.name}."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "fight"
    },
    {
     "fact": "cutLoser.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "We've lost {cutMan.name}. They're bringing the stretcher out.",
     "{cutMan.name} isn't getting up. The trainers are with him, and it doesn't look good."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "death"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "He's been everywhere tonight. You can't leave him alone in front like that.",
     "Three goals. Somebody on that bench should have put a body on him an hour ago."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "hattrick"
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "That's on the defence. Somebody lost his man.",
     "Now it's a different game. They'll both be careful with the puck."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b8",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Now they have to hold on, and that's the hard part.",
     "Every shift matters from here. You don't give the puck away."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "late"
    },
    {
     "fact": "cutTied",
     "op": "=",
     "value": "false"
    }
   ]
  },
  {
   "id": "b9",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{cutLoser.name} picked the wrong man. I played against guys like {cutMan.name}, and you leave them alone.",
     "{cutLoser.name} will want that one back. It wasn't close."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "fight"
    }
   ]
  },
  {
   "id": "b10",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "He'll be back from the vat. It's still hard to watch.",
     "You never get used to that. They'll print him again, but still."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "cut",
     "op": "=",
     "value": "death"
    }
   ]
  },
  {
   "id": "b11",
   "shot": {
    "cam": "cam2",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Back to the ice.",
     "Let's get back down there."
    ]
   },
   "gfx": []
  }
 ]
}
